import sqlite3

class Calendar:
    def __init__(self):
        self.conn = sqlite3.connect(':memory:')
        self.cursor = self.conn.cursor()
        self.cursor.execute('CREATE TABLE meetings (start_time INTEGER, end_time INTEGER)')

    def add_meeting(self, start_time, end_time):
        self.cursor.execute('INSERT INTO meetings VALUES (?, ?)', (start_time, end_time))
        self.conn.commit()

    def is_conflicting(self, start_time, end_time):
        self.cursor.execute('SELECT * FROM meetings WHERE (start_time <= ? AND end_time >= ?) OR (start_time >= ? AND end_time <= ?)', (end_time, start_time, start_time, end_time))
        return bool(self.cursor.fetchone())

# Example usage
if __name__ == '__main__':
    calendar = Calendar()
    calendar.add_meeting(1000, 2000)
    print(calendar.is_conflicting(1500, 3000))

