from sqlite3 import connect
data = """
CREATE TABLE employees (
    id INTEGER PRIMARY KEY,
    name TEXT,
    manager_id INTEGER
);
INSERT INTO employees (id, name, manager_id) VALUES (1, 'Alice', NULL), (2, 'Bob', 1), (3, 'Charlie', 1), (4, 'David', 2);
"""
db = connect(':memory:')
cursor = db.cursor()
cursor.executescript(data)
cursor.execute('SELECT * FROM employees')
employees = cursor.fetchall()
def build_hierarchy(employees):
    manager_dict = {emp[0]: [] for emp in employees}
    root = None
    for emp in employees:
        if emp[2] is None:
            root = emp
        else:
            manager_dict[emp[2]].append(emp)
    def build_node(node):
        return {'name': node[1], 'children': [build_node(child) for child in manager_dict[node[0]]]}
    return build_node(root)
hierarchy = build_hierarchy(employees)

